// Additional original systems lessons. Examples state their model and execution boundary.
const reference = (label, url, section) => ({ label, url, section });
const ost = (file, section) => reference('OSTEP: ' + section, 'https://pages.cs.wisc.edu/~remzi/OSTEP/' + file + '.pdf', section);
const osc = section => reference('Operating System Concepts, tenth edition: ' + section, 'https://www.os-book.com/OS10/slide-dir/index.html', section);
const prose = (title, ...paragraphs) => ({ type: 'prose', title, paragraphs });
const table = (caption, columns, rows) => ({ type: 'table', caption, columns, rows });
const trace = (caption, columns, rows) => ({ type: 'trace', caption, columns, rows });
const steps = (title, items) => ({ type: 'steps', title, items: items.map(([title,text]) => ({title,text})) });
const code = (title, language, source, ...notes) => ({type:'code', title, language, code:source, notes});
const exercise = (title, prompt, tasks, solution, checks) => ({type:'exercise',title,prompt,tasks,solution,checks});
const topic = (id, sectionId, title, intro, blocks, references) => ({id,sectionId,title,intro,blocks,references});
export const systemsFurtherHandbook = {};

systemsFurtherHandbook['user-mode'] = [
  topic('kernel-service-boundaries', 'contract', 'Place kernel services and trace the cost of each protection boundary', [
    'An operating system supplies services such as execution, memory management, file access, device control, communication, and accounting. Its organization determines which components share privileged memory and which communicate through protected interfaces. Draw both the call path and the authority of each participant; a function boundary and a privilege boundary provide different guarantees.',
    'A monolithic organization places many services in one privileged address space. A microkernel moves selected services into separate processes and retains a smaller privileged mechanism set. A layered design constrains dependencies between levels, and loadable modules let components join a running kernel. These classifications describe design choices that can coexist in one system.'
  ], [
    table('Choose a location for three services', ['Service', 'Privileged implementation', 'Separate service process'], [['Filesystem namespace','Calls the block layer through internal interfaces','Receives messages and holds explicit authority to a block service'],['Device driver','Can access kernel memory and authorized device registers','Needs controlled device mappings, interrupts, and a DMA isolation policy'],['Network policy','Shares kernel synchronization and failure domain','Can restart independently when its protocol and retained state permit recovery']]),
    trace('An illustrative uncached read through two service processes', ['Handoff', 'Sender and receiver', 'Privilege transitions in this model'], [['1','Application sends request to filesystem service through kernel IPC','User to kernel, kernel to service: 2'],['2','Filesystem service requests data from driver service','Service to kernel, kernel to driver: 2'],['3','Driver sends completion to filesystem service','Driver to kernel, kernel to service: 2'],['4','Filesystem service returns the read result','Service to kernel, kernel to application: 2']]),
    prose('Compute a cost model without hiding assumptions',
      'Assume each privilege transition costs 0.4 microseconds and the actual service work totals 12 microseconds. The four handoffs above contain eight transitions, giving 12+8*0.4=15.2 microseconds before copies, queueing, and cache effects. A model with one application-to-kernel request and one return contains two transitions, giving 12.8 microseconds. The difference is 2.4 microseconds under these chosen constants. Real IPC implementations can change the handoff path and use shared memory, batching, or direct scheduling optimizations.',
      'A separate process boundary limits direct memory access according to its mappings, but a driver with unrestricted DMA can still reach memory outside its CPU address space. Device assignment therefore needs an IOMMU or another adequate containment mechanism. Likewise, restarting a filesystem service requires a plan for open handles and in-flight operations. Process separation makes some recovery possible; the service protocol determines what recovery means.'),
    steps('Evaluate an organization for a concrete request', [['List authorities','Identify who can alter page tables, issue device commands, inspect credentials, and modify persistent metadata.'],['Trace every transfer','Record message copies, shared-buffer ownership, address-space changes, and scheduler decisions.'],['Define failure outcomes','For a driver crash, state which requests fail, which resources are reclaimed, and which components retain enough state to continue.'],['Measure the target workload','Compare small requests, large transfers, batching, and contention. The cost of a boundary depends on how often the workload crosses it.']]),
    prose('Keep modules and dependency layers precise',
      'A module loaded into kernel privilege normally joins the kernel’s memory and failure domain. Its separate source tree or loadable file provides deployment modularity while memory protection follows the execution environment. A layer can also exist entirely inside one address space: requiring the filesystem to call a block interface prevents dependency cycles, even when calls use ordinary instructions.',
      'For the course kernel, start with an interface ledger: inputs, outputs, sleeping rules, lock requirements, ownership transfer, and errors for each service. This ledger remains useful if a later version moves a driver into a process. The protocol can evolve from function arguments to messages while retaining the documented operation semantics.'),
    exercise('Batch eight small requests', 'Assume each request needs 3 microseconds of service work. The service-process model uses eight transitions per request at 0.4 microseconds each. A batch handles all eight requests with one set of eight transitions.', ['Calculate individual-request and batched total costs.', 'Name one cost and one failure consequence that this arithmetic excludes.'], ['Individual execution costs 8*(3+8*0.4)=49.6 microseconds. The batch costs 8*3+8*0.4=27.2 microseconds under the model.', 'The arithmetic excludes queueing and memory-copy costs. A failed batch also needs a per-request completion contract so callers know which operations took effect.'], ['Individual total 49.6; batch total 27.2 microseconds.', 'Each request retains its own result identity.'])
  ], [osc('Chapter 2: Operating-system services and structures'), ost('cpu-mechanisms','Chapter 6: Limited Direct Execution')]),

  topic('syscall-versioned-request-transaction', 'copy', 'Validate a versioned syscall request from one kernel-owned snapshot', [
    'A syscall interface becomes difficult to extend when callers and kernels interpret the same bytes differently. Fixed-width fields, an explicit structure size, a version, and reserved-zero fields make the agreement inspectable. Define the serialized layout independently of compiler padding, then specify which combinations the kernel accepts.',
    'Consider a new teaching request copied through the existing course syscall entry. Version 1 is 24 bytes: six little-endian 32-bit fields. Version 2 is 32 bytes and adds a 64-bit deadline. This is an illustrative future interface, so its operation number must come from the kernel’s shared syscall table when implemented.'
  ], [
    table('Exact request layout', ['Byte offsets', 'Field', 'Validation'], [['0..3','size','24 for version 1; 32 for version 2'],['4..7','version','Accept only implemented versions'],['8..11','flags','Only documented bits may be set'],['12..15','reserved','Must be zero'],['16..19','user_buffer','32-bit user address under the course address-space split'],['20..23','buffer_length','Bounded byte count'],['24..31, version 2','deadline','Little-endian 64-bit time in the documented clock domain']]),
    trace('A check/use race inside one request', ['Step', 'Kernel action', 'Concurrent caller action'], [['1','Reads user buffer_length as 16 and approves it','Keeps access to the request page'],['2','Allocates a 16-byte kernel buffer','Changes user buffer_length to 4096'],['3, broken path','Reads buffer_length again during copy','The second read supplies a different size']]),
    prose('Make validated fields stable',
      'Copy a bounded request representation into kernel-owned storage and use only that snapshot for subsequent parsing and dispatch. If a short header is first read to determine how much to copy, the full copy must revalidate its own size and version. The caller can change bytes between the two reads. Reject a mismatch or interpret the final bounded snapshot according to a rule that keeps every access inside the copied region.',
      'The versioned record is a deliberate teaching protocol. Linux ioctl guidance commonly uses a new command number for an incompatible interface, preserving the old command’s interpretation. Both designs require an explicit compatibility policy. Snapshotting the request structure does not stabilize the memory named by its user_buffer field. The payload copy still needs a fault-aware user-copy routine and a policy for concurrent unmapping or modification. A write-to-device operation can copy input bytes into private kernel storage before submission. A large asynchronous operation may use pinned pages or retained mappings, with clearly defined ownership until completion.'),
    steps('A bounded request transaction', [['Bound the header access','Ensure the small header range is representable and accessible through the user-copy mechanism.'],['Choose a maximum copy','Reject sizes above a fixed API limit before allocation. Here the implemented maximum is 32 bytes.'],['Copy and revalidate','Copy the chosen byte count, then check version, exact size, flags, and reserved bytes inside the kernel snapshot.'],['Validate referenced resources','Check buffer range, descriptor rights, and maximum transfer size; acquire references needed during execution.'],['Commit or unwind','Publish asynchronous work only after resources are complete. On failure, release temporary buffers and references without installing a partial request.']]),
    code('Overflow-safe range policy for this 32-bit model', 'c', `#include <stdint.h>
int request_range(uint32_t address, uint32_t length) {
    const uint32_t split = 0xc0000000u;
    if (length == 0) return 1;
    if (address < 0x1000u || address >= split) return 0;
    return length <= split - address;
}`,
      'This helper checks arithmetic and the chosen lower guard/user split. Mapping permissions and fault handling are separate checks.',
      'Subtracting only after verifying address<split avoids overflow in address+length. A zero-length request follows the explicitly permissive model rule.'),
    exercise('Handle an old kernel and a changed header', 'An old kernel supports only version 1. A caller supplies version 2, size 32. Separately, a caller changes size from 24 to 32 between the header copy and a 24-byte full copy.', ['State the outcome of each request.', 'Evaluate address 0xbffffff0 with lengths 16 and 17.'], ['The old kernel rejects the unsupported version with its documented compatibility error. The second request fails snapshot revalidation because the copied size claims bytes outside the 24-byte snapshot; the kernel must not read the missing deadline.', 'The remaining space below the split is 0x10, or 16 bytes. Length 16 fits; length 17 fails the arithmetic range policy.'], ['No read beyond the copied request.', 'Range answers: accept 16, reject 17.'])
  ], [osc('Chapter 2: System calls and parameter passing'), reference('Linux ioctl API design guidance','https://docs.kernel.org/driver-api/ioctl.html','Fixed-width structures, compatibility, and extensible interfaces')])
];

systemsFurtherHandbook['threads-and-scheduling'] = [
  topic('thread-mappings-amdahl-performance', 'measure', 'Map user threads to kernel threads and calculate the parallel speedup limit', [
    'A language runtime can schedule its own execution contexts, while the kernel schedules the entities it knows about. The mapping between these levels determines parallelism and what happens when one context enters a blocking syscall. Define a user thread as a runtime-managed continuation and a kernel thread as an independently schedulable kernel entity.',
    'With many-to-one mapping, many user continuations share one kernel thread. With one-to-one mapping, each user thread has a kernel counterpart. A many-to-many runtime schedules many continuations over a pool of kernel workers. These models differ in resource cost, blocking behavior, and coordination between two schedulers.'
  ], [
    table('Three mapping models on a four-core machine', ['Mapping', 'Maximum simultaneous execution in this example', 'Blocking consequence'], [['Eight user threads on one kernel thread','One user thread','A blocking syscall can suspend their only worker unless the runtime avoids or compensates for it'],['Eight user threads on eight kernel threads','Up to four threads, limited by cores','A blocked thread leaves other kernel threads eligible'],['Eight user threads on two kernel workers','Up to two threads','One blocking worker leaves one available; the runtime may grow or replace workers under its policy']]),
    prose('Distinguish waiting overlap from parallel computation',
      'An event-aware runtime can switch away from a user continuation awaiting network readiness while its kernel worker serves another continuation. This overlaps waiting with useful work on one core. Two CPU-bound continuations can execute simultaneously only when the runtime has at least two scheduled workers on available cores. Concurrency describes overlapping lifetimes; the parallel execution count depends on workers, cores, and resource limits.',
      'Runtime scheduling also needs a rule for task-local state. A continuation can migrate between workers, so ordinary worker-local storage identifies the worker and can differ from the logical request’s own state. A library that holds a kernel-thread-affine resource across a migration point requires pinning or another explicit compatibility mechanism. The mapping model affects correctness as well as speed.'),
    trace('Amdahl calculation for an original workload', ['Component', 'One-core time', 'Four-core ideal time'], [['Serial setup and merge','18 ms','18 ms'],['Perfectly divisible parallel work','72 ms','72/4 = 18 ms'],['Total','90 ms','36 ms'],['Speedup','Reference 1','90/36 = 2.5']]),
    prose('Derive the formula and add real costs',
      'Let fraction s of the original runtime be serial and divide the remainder perfectly across p processors. Normalized time becomes s+(1-s)/p, so speedup is 1/[s+(1-s)/p]. Here s=18/90=0.2. With eight processors, time is 18+72/8=27 ms and speedup is 90/27, approximately 3.333. Even infinitely many processors leave the 18 ms serial component, giving a limit of five.',
      'Suppose the four-worker version also spends 6 ms on dispatch, synchronization, and cache effects. Its time becomes 42 ms and speedup falls to about 2.143. Measure those costs separately from the serial fraction so a change in runtime machinery has an identifiable effect. Memory bandwidth can also stop the parallel part from scaling as 1/p; Amdahl’s ideal arithmetic then overestimates the achievable result.'),
    steps('Build a useful scaling experiment', [['Hold the workload fixed','Use the same input and verify equivalent output at every worker count.'],['Record execution and waiting','Measure CPU time, elapsed time, runnable delays, and I/O waits where available.'],['Change one count','Vary worker count while keeping core allocation and request volume documented.'],['Explain saturation','Identify serial sections, lock contention, queue bottlenecks, bandwidth limits, or insufficient runnable tasks before adding workers.']]),
    exercise('Choose a worker pool', 'A workload needs 12 ms of serial work and 48 ms of perfectly parallel work. It runs on six available cores, but the runtime currently has three kernel workers.', ['Compute ideal runtime and speedup with three workers and then six.', 'Explain why six workers can still provide little benefit if the parallel stage saturates memory bandwidth at three.'], ['Three workers give 12+48/3=28 ms, so speedup is 60/28=15/7, approximately 2.143. Six give 12+8=20 ms and speedup 3.', 'The ideal division assumes additional workers increase useful processing rate. If three already consume the available memory bandwidth, more workers contend for the same throughput and may add synchronization cost.'], ['Three workers: 28 ms; six workers: 20 ms under ideal assumptions.', 'The asymptotic speedup limit is 60/12=5.'])
  ], [ost('threads-intro','Chapter 26: Concurrency and Threads'), osc('Chapter 4: Multithreading models and Amdahl’s law')])
];

systemsFurtherHandbook['ipc-and-synchronization'] = [
  topic('event-loop-continuations-readiness', 'fairness', 'Turn a stream parser into a nonblocking event-loop state machine', [
    'An event loop repeatedly waits for readiness notifications, advances eligible operations by a bounded amount, and records the state needed for the next turn. A readiness event means an operation may make progress. Another consumer, a race, or an implementation detail can leave the next nonblocking call unable to proceed, so the result of that call remains authoritative.',
    'Use a framed byte stream with a four-byte big-endian length followed by that many payload bytes. Bound the payload at 65536 bytes. One connection record stores parser phase, header bytes received, decoded length, payload bytes received, pending output, and an identity generation. These fields form the continuation normally preserved by a blocking function’s stack.'
  ], [
    trace('A five-byte frame arrives in three fragments', ['Event', 'Bytes obtained', 'Saved continuation afterward'], [['First readable turn','00 00','HEADER phase, 2 of 4 header bytes received'],['Second readable turn','00 05 41 42 43','Header complete, length=5; PAYLOAD phase, 3 of 5 bytes received'],['Third readable turn','44 45','Frame complete: payload ABCDE; parser can dispatch it'],['Next attempted read','Would-block result','Preserve state and wait for another eligible turn']]),
    code('Bounded readiness handler', 'text', `on_readable(connection):
    budget = 4096
    while budget > 0:
        target = next_unfilled_header_or_payload_slice(connection)
        result = nonblocking_read(target, min(target.length, budget))
        if result == WOULD_BLOCK: return WAITING
        if result == EOF: return finish_or_report_truncated_frame()
        if result is ERROR: return fail_connection(result)
        advance_parser(result.bytes)
        budget -= result.bytes
        if header_complete:
            reject lengths above 65536 before allocation
        if frame_complete:
            queue_bounded_application_work()
            reset_parser_for_next_frame()
    enqueue_connection_for_another_turn()`,
      'A zero-length payload completes immediately after its header; the implementation must advance that parser state without issuing a zero-length read and misclassifying its zero result as EOF.',
      'The queue for completed application work also has a limit. When it fills, suspend input interest or retain bounded pending state until downstream capacity returns.'),
    prose('Coordinate readiness and fairness',
      'A handler that drains an unlimited stream can monopolize the loop. A byte or time budget returns control so other connections receive service. With level-triggered readiness, an unread ready source normally remains eligible. With edge-triggered readiness, stopping before reaching would-block requires an explicit runnable continuation or another correct rearming protocol; waiting for a fresh edge while old bytes remain can stall the connection.',
      'CPU-heavy work and genuinely blocking operations also need a policy. A worker pool can perform a slow operation and post a completion back to the loop. The loop owns connection state while workers receive bounded immutable requests or explicitly transferred buffers. A single accidentally blocking name lookup or file access can otherwise delay every connection served by that worker.'),
    prose('Protect the continuation’s lifetime',
      'Suppose descriptor 7 belongs to connection generation 4, closes, and is quickly reused for generation 5. A queued callback naming only descriptor 7 could attach an old completion to the new connection. Include a generation or stable object reference and validate it before mutating state. Cancellation also needs to prevent the last reference from being freed while a worker can still post completion.',
      'Async syntax can compile a function into this kind of state machine. Its suspension points identify where local state must survive. The executor still needs correct wake registration and scheduling. A task can test readiness, register its wake mechanism, and recheck under the appropriate protocol to close a check/register race. Language support changes how the continuation is expressed; the readiness and ownership proof remains explicit.'),
    exercise('Stop at a fairness budget', 'A connection has 9000 readable bytes. Each handler turn consumes at most 4096, and the event source uses edge-triggered notification.', ['Compute the bytes handled in successive turns.', 'Explain the required action after the first two turns and the treatment of a stale generation-4 callback.'], ['The turns consume 4096, 4096, and 808 bytes. After each budget-limited turn, queue another runnable continuation because readable bytes may remain without a new edge.', 'A callback for generation 4 must fail its identity check after descriptor reuse for generation 5. Release any old completion resources through their ownership protocol without modifying the new connection.'], ['4096+4096+808=9000.', 'Budget exhaustion preserves a path to future execution.'])
  ], [ost('threads-events','Chapter 33: Event-based Concurrency'), reference('Writing an OS in Rust: Async/Await','https://os.phil-opp.com/async-await/','Continuations, executors, wakers, and task lifetime'), osc('Chapter 12: I/O readiness and asynchronous operations')]),

  topic('duplex-message-protocol-backpressure', 'ownership', 'Design a two-way message channel with identities, bounded queues, and closure', [
    'A byte pipe supplies ordered bytes in one direction. A two-way service channel needs additional decisions: message framing, request identity, reply correlation, buffer ownership, capacity, and closure. Even inside one machine, two endpoints can make progress at different rates or fail independently, so these rules belong to the IPC contract.',
    'Consider one client sending two requests to a service that can complete them out of order. Each request carries a 32-bit identifier, opcode, flags, and a bounded payload. The client stores a pending entry keyed by identifier. A reply resolves that entry regardless of its arrival order.'
  ], [
    table('An illustrative eight-byte message header', ['Bytes', 'Field', 'Validation'], [['0..1','Payload length, big-endian','At most 256 in this small protocol'],['2','Opcode','Known request or reply operation'],['3','Flags','Reject unsupported bits'],['4..7','Request identifier, big-endian','Unique among this endpoint’s outstanding operations']]),
    trace('Replies can cross without confusing their owners', ['Time', 'Channel event', 'Client pending table'], [['0','Send request 17: checksum buffer A','17 -> callback for A'],['1','Send request 18: inspect object B','17 -> A; 18 -> B'],['2','Reply 18 arrives first','Complete B and remove entry 18; retain 17'],['3','Reply 17 arrives','Complete A and remove entry 17'],['4','An unexpected reply 18 arrives','Apply the duplicate/late-reply policy; never resolve an unrelated future request']]),
    prose('Bound capacity in both directions',
      'Suppose each direction has four message slots. Endpoint A tries to send five messages before reading, and endpoint B does the same. Each fills its outgoing queue and blocks on its fifth send. Neither reaches its receive loop, although both incoming queues contain work. This is a protocol-level deadlock produced by symmetric batching.',
      'A nonblocking pump can alternate draining incoming messages with sending queued output. Another protocol reserves capacity for replies or control messages, with credits that bound data requests. Reserving one of four slots leaves at most three data messages outstanding in that direction. The proof must account for every operation that can consume the reserved slot; labeling a slot “control” while allowing ordinary requests to occupy it breaks the guarantee.'),
    steps('Receive and dispatch one framed message', [['Validate the fixed header','Check that eight header bytes exist, decode the length, and reject unsupported opcodes and flags before allocating payload storage.'],['Validate the complete range','Require payload length to fit within the received frame using subtraction-based bounds. Define whether trailing bytes begin another message or are invalid.'],['Acquire or transfer ownership','Copy small payloads, or retain a validated shared-buffer handle with explicit rights and lifetime. A raw pointer alone cannot transfer authority across address spaces.'],['Dispatch with a budget','Limit concurrent requests and queue length. Return a documented busy result or backpressure signal when capacity is exhausted.'],['Correlate completion','Send the original request identity with the result, then release resources exactly once according to the endpoint’s cancellation and closure states.']]),
    prose('Close each half deliberately',
      'Half-close ends sending while allowing already queued replies to be received. Full close terminates both directions and resolves or cancels outstanding operations under the API’s rules. An endpoint should distinguish “peer finished sending,” “peer failed,” and “local cancellation requested” if applications need different recovery behavior. Buffered complete messages can be drained according to the chosen contract.',
      'Identifier reuse needs a rule across reconnects. An incarnation number paired with the request identifier can distinguish a new channel from late work belonging to an old one. If the protocol carries shared-memory handles, closing the transport must also release or revoke those handles after in-flight accesses finish. Queue closure alone does not end every buffer lifetime.'),
    exercise('Repair symmetric batching', 'Two endpoints each have a four-slot outbound queue and each tries to send six data messages before receiving anything.', ['Show the first blocked state.', 'Design a bounded event-loop policy that can make progress, and state the pending identifiers after replies 23 then 21 arrive for outstanding requests 21,22,23.'], ['Both endpoints queue four messages and block on message five. A policy using nonblocking send and receive can drain incoming work whenever sending would block, while bounding local unsent messages.', 'Reply 23 removes entry 23 and reply 21 removes entry 21; entry 22 remains. The transport must preserve request identity even when service completion order differs from request order.'], ['No endpoint waits only for outbound space while refusing available input.', 'Pending set becomes {22}.'])
  ], [osc('Chapter 3: Message passing, buffering, and communication'), ost('threads-events','Chapter 33: Event-based Concurrency')])
];

systemsFurtherHandbook['block-devices'] = [
  topic('tagged-block-requests-multiplexing', 'layers', 'Merge, dispatch, and complete tagged block requests under a queue-depth limit', [
    'A block interface lets multiple callers share one device while preserving each request’s result and buffer lifetime. Requests carry an operation, starting logical block address, count, buffer references, and completion identity. A software queue decides what to dispatch; the device may complete dispatched work in a different order.',
    'A tag identifies one in-flight request slot. A bounded tag pool limits concurrency and provides a fast lookup when the device reports completion. Reusing a numeric tag requires coordination with completion and cancellation so an old event cannot be mistaken for a new operation.'
  ], [
    table('Merge only compatible neighbors', ['Request', 'Operation and sectors', 'Possible merged form'], [['A','Read sectors 40..43, count 4','A+B can become read 40..45, count 6'],['B','Read sectors 44..45, count 2','Compatible direction, adjacency, flags, and buffer representation required'],['C','Write sector 46, count 1','Separate because the operation differs'],['D','Read sector 100, count 1','Separate because the range is distant']]),
    prose('Preserve the original completion obligations',
      'With 512-byte sectors, the merged A+B request transfers 6*512=3072 bytes. The merge must respect the device’s maximum transfer length and scatter/gather limits. A merged command still represents two caller requests: completing the first four sectors and failing the remainder requires a documented way to report each caller’s progress. Discarding the original boundaries would lose that information.',
      'Ordering constraints can prohibit a merge or dispatch reordering. A flush, a durability dependency, or overlapping writes may require earlier work to reach a specified state first. The scheduler must retain these relationships even when adjacent LBAs would otherwise look mergeable. Device command submission order and durable completion order can differ under the device’s cache contract.'),
    trace('Out-of-order completion through a four-slot tag table', ['Event', 'Tag and generation', 'Owner/result'], [['Dispatch A+B','Tag 0, generation 12','Merged read with two retained caller records'],['Dispatch C','Tag 1, generation 8','Write request C'],['C completes first','Tag 1, generation 8','Notify C, release its references, return tag 1'],['Dispatch D','Tag 1, generation 9','New owner is D'],['Late duplicate completion for C','Tag 1, generation 8','Reject against current generation 9; preserve D'],['A+B completes','Tag 0, generation 12','Resolve A and B according to their original ranges']]),
    steps('Submit through a bounded queue', [['Validate the request','Check operation, LBA range, byte count, alignment, and owned buffer references.'],['Try a legal merge','Combine only requests compatible in operation, ordering, adjacency, and device limits.'],['Acquire a tag','If the pool is empty, queue or block the submitter under a bounded admission policy.'],['Publish the command','Install the tag-table owner before making the descriptor visible to the device.'],['Complete exactly once','Validate completion identity and status, account for original callers, release device ownership, and only then make the tag reusable.']]),
    prose('Relate queue depth to measured latency',
      'Little’s law relates the long-run average number of in-flight operations L to throughput lambda and average time in the system W: L=lambda*W for a stable measurement boundary. At 20000 operations per second and 0.4 ms average latency, L=20000*0.0004=8. This observation suggests that an average of eight requests must be outstanding at that boundary; queue depth eight alone does not guarantee the device can deliver that throughput.',
      'At 4096 bytes per operation, that throughput transfers 81920000 bytes per second, or 78.125 MiB/s. Compare it with the device’s bandwidth and CPU processing cost. Increasing the queue beyond the useful concurrency can raise waiting time without raising throughput. Record median and tail latency together with throughput when selecting a limit.',
      'The generation example assumes completions carry a verifiable generation or epoch. Hardware reporting only a numeric tag requires a different reuse protocol, such as draining or resetting the queue before an old completion could collide with a new owner. Generation checks protect software dispatch from stale completion identity. They do not stop a device from writing into a buffer whose DMA remains active. A canceled request retains its buffer until the driver proves device access has ceased, then returns its tag and resources under the cancellation protocol.'),
    exercise('Size the measured in-flight population', 'A stable workload completes 12000 requests per second with mean request latency 0.75 ms. Each request carries 8 KiB.', ['Compute the average number of in-flight requests and payload bandwidth.', 'State why tags and retained caller records are still required if every request happens to complete in order during this test.'], ['L=12000*0.00075=9. Payload bandwidth is 12000*8192=98304000 bytes/s, or 93.75 MiB/s.', 'The device contract can permit different ordering or failures in another run. Tags identify the actual owner, and retained boundaries preserve per-caller results after merging or partial completion.'], ['Average in flight 9; bandwidth 93.75 MiB/s.', 'Resources remain owned until actual completion or proven cancellation.'])
  ], [reference('Linux multi-queue block I/O documentation','https://docs.kernel.org/block/blk-mq.html','Software queues, hardware queues, tags, and request dispatch'), osc('Chapters 11 and 12: Storage queues and I/O scheduling'), ost('file-devices','Chapter 36: I/O Devices')])
];

systemsFurtherHandbook['fat-write-driver'] = [
  topic('filesystem-run-allocation-fragmentation', 'allocate', 'Allocate free runs and measure fragmentation before choosing an extent', [
    'Free-space accounting answers how many blocks are available. An allocation policy also asks where they are and how they can be grouped. A contiguous request can fail even when the total free count is large enough. Represent a free run as a starting block and a length, then state whether the operation requires one run or permits several extents.',
    'Use a 64-block teaching volume whose free runs are (4,3), (12,6), (30,4), and (44,9). Each pair means start and count. There are 22 free blocks, but the largest contiguous run contains nine. This example describes a general allocator; a FAT driver can maintain a derived search index while checking actual FAT entries as its allocation authority.'
  ], [
    table('Compare policies for a four-block request', ['Policy', 'Chosen blocks', 'Effect on the free-run list'], [['First fit in ascending address order','12..15','Run (12,6) becomes (16,2)'],['Best fit by smallest sufficient run','30..33','Run (30,4) disappears exactly'],['Nearest suitable run to block 50','44..47 in this simple policy','Run (44,9) becomes (48,5)']]),
    prose('Derive a multi-extent fallback',
      'A ten-block request cannot fit in one run. Taking the largest run first can use nine blocks at 44 and one at 4, producing two extents. Taking available space in ascending order uses three at 4, six at 12, and one at 30, producing three. Fewer extents reduce mapping records, while placement near related data may reduce other access costs. Define which goal the policy optimizes and which fallbacks it permits.',
      'First fit over an unsorted run array can scan O(r) records for r runs. Best fit also scans O(r) without an index; a size-ordered tree can improve search while requiring updates whenever a run splits or coalesces. Freeing a range must detect overlap with already free space and combine adjacent compatible runs. Otherwise double-free bugs can award the same blocks to two files.'),
    code('Find and reserve one run in a 64-bit free bitmap', 'c', `#include <stdint.h>
int reserve_run(uint64_t *free_bits, unsigned count, unsigned *start) {
    if (!free_bits || !start || count == 0 || count > 64) return 0;
    unsigned run = 0, begin = 0;
    for (unsigned i = 0; i < 64; ++i) {
        if ((*free_bits >> i) & UINT64_C(1)) {
            if (run == 0) begin = i;
            ++run;
            if (run == count) {
                uint64_t next = *free_bits;
                for (unsigned j = 0; j < count; ++j)
                    next &= ~(UINT64_C(1) << (begin + j));
                *free_bits = next;
                *start = begin;
                return 1;
            }
        } else run = 0;
    }
    return 0;
}`,
      'A one bit means free. The caller holds the allocation lock across this operation. Failed searches leave both outputs unchanged.',
      'Every shift index is below 64. The second loop clears a proven run only after the first loop finds all requested blocks.'),
    prose('Account for two kinds of waste',
      'External fragmentation describes free capacity split into inconvenient gaps. Internal slack is unused space inside the allocation unit already assigned to a file. With 4096-byte clusters, an 8500-byte file requires three clusters, totaling 12288 bytes and leaving 3788 bytes of tail slack. Extents can describe adjacent clusters compactly, while the cluster size still determines that slack.',
      'Reservation, persistent allocation, and file publication remain separate states. A concurrent allocator must see an in-memory reservation immediately; recovery after power failure sees only durable metadata. If writing initialized data fails after reservation, release the reserved run or retain enough recovery information to reclaim it. Never publish a file mapping to blocks still considered free by another allocator path.'),
    exercise('Explain a failed large request', 'Start from the four original free runs and request ten contiguous blocks. Then permit up to two extents.', ['State the first outcome despite the total free count.', 'Give a valid two-extent allocation and compute the remaining free total.'], ['The contiguous request fails because the maximum run is nine, even though 22 blocks are free.', 'Allocate nine blocks beginning at 44 and one beginning at 4. The operation consumes ten blocks and leaves twelve free. The remaining part of the first run begins at 5 with length two.'], ['Maximum run 9; total free 22.', 'Two-extent fallback leaves 12 free blocks.'])
  ], [ost('file-ffs','Chapter 41: Locality and allocation'), osc('Chapter 14: Allocation methods and free-space management')])
];

systemsFurtherHandbook['fat-read-driver'] = [
  topic('file-access-offsets-append-holes', 'read', 'Specify random access, concurrent append, and sparse-file behavior', [
    'A file interface needs a rule for how a request chooses its byte range. Ordinary read and write commonly use an offset stored in an open-file description. Positioned operations take an explicit offset for that call. Append mode chooses an end-of-file position under the filesystem’s append contract. These choices determine how concurrent callers interact.',
    'The following examples use a Unix-like local filesystem model. A FAT implementation must translate supported operations into its cluster-chain representation and explicitly reject or emulate features its on-disk format cannot represent directly.'
  ], [
    trace('Separate lseek and read can race on a shared offset', ['Step', 'Thread A', 'Thread B', 'Shared offset'], [['1','Seek to 100','Idle','100'],['2','Paused','Seek to 200','200'],['3','Read ten bytes','Idle','A reads bytes 200..209; offset becomes 210']]),
    prose('Use a positioned operation when the offset is an argument',
      'A pread-style call requests bytes at an explicit offset while leaving the shared open-file offset unchanged. In the trace, pread at 100 can select the intended bytes despite another thread’s seek. The kernel still needs range validation, mapping synchronization, and a rule for a concurrent truncate. Providing the offset atomically solves the seek/read coordination problem; it does not freeze file contents.',
      'Two independent opens usually create separate open-file descriptions and therefore separate offsets. Duplicating or inheriting a descriptor can preserve a shared description. A library should document which object it duplicates before assigning one descriptor number to each worker. Different descriptor numbers alone give no guarantee of independent offset state.'),
    table('Two appenders begin with a twenty-byte file', ['Operation sequence', 'Possible byte ranges', 'Result'], [['Serialized append operations of lengths 4 then 6','20..23, then 24..29','File reaches size 30 with disjoint appended ranges'],['Both callers seek to observed EOF, then write','Both can choose starting offset 20','The second write can overwrite part of the first'],['One logical record uses several append calls','Another writer may append between those calls','Application record fragments can interleave']]),
    prose('Define the application’s atomic unit',
      'An append operation needs atomic selection of the file’s current end and placement of its write under the filesystem’s stated guarantees. A logical log record split across three system calls spans three such opportunities. Use one bounded operation where the API guarantees the required behavior, or coordinate complete records with a lock or record-oriented service. Partial writes still require progress accounting.',
      'Advisory locks coordinate cooperating applications; an application that ignores them may still issue conflicting I/O. A mandatory access rule would require the kernel to enforce a different contract. Locks also need ownership, release-on-exit, and interaction-with-fork rules. Specify these details when introducing a locking API into a teaching kernel.'),
    trace('A sparse extent-capable file receives three bytes at offset 8192', ['Quantity', 'Value', 'Explanation'], [['Logical size','8195 bytes','Highest written offset 8194 plus one'],['Logical blocks at 4096 bytes','0,1,2','The write touches only block 2'],['Data allocation in the simple model','One data block','Blocks 0 and 1 remain holes if the filesystem supports them'],['Reading the gap','8192 zero bytes','The logical read contract supplies zeros for holes']]),
    prose('Connect access semantics to storage representation',
      'A hole represents a logical range with no ordinary data-block allocation. An extent tree can encode that absence, and a reader supplies zero-filled bytes for the gap. FAT’s ordinary cluster chain does not provide the same sparse-hole mapping. A FAT driver extending a file across a gap may allocate clusters and initialize the intervening logical bytes, or reject an unsupported sparse operation according to its interface.',
      'A memory mapping can retain a file reference after the original descriptor closes. Shared mapped writes, buffered I/O, truncation, and durability operations must follow the filesystem and virtual-memory coherence contract. A first implementation can support read-only mappings or omit mappings while its page-cache lifetime rules are established. Report the supported access modes explicitly so an application can choose a valid strategy.'),
    exercise('Choose offsets for parallel readers', 'Two workers share a duplicated descriptor. Worker A needs bytes 0..99 and worker B needs 100..199. The file is stable for this exercise.', ['Choose calls that avoid coordination through the shared seek position.', 'Compute size and gap length if a new sparse file receives four bytes at offset 12288.'], ['Use positioned reads with offsets 0 and 100 and counts 100 each. Each worker handles short results while preserving its own requested offset progression.', 'The new logical size is 12292 and the gap before the write is 12288 bytes. With 4096-byte blocks, three preceding logical blocks can remain holes in an extent-capable filesystem.'], ['Offsets belong to individual requests.', 'Sparse logical size 12292.'])
  ], [ost('file-intro','Chapter 39: File interfaces and offsets'), osc('Chapter 13: Access methods and file-sharing semantics'), reference('Linux positioned read/write interface','https://man7.org/linux/man-pages/man2/pread.2.html','Explicit offsets and unchanged open-file position')])
];

systemsFurtherHandbook['libc-and-shell'] = [
  topic('signals-process-groups-terminal-jobs', 'session', 'Make a shell control foreground jobs through signals and process groups', [
    'A shell job can contain several processes in one pipeline. A process group identifies that set so the terminal and shell can direct control events to the whole job. A session organizes process groups around a controlling terminal. The terminal records which process group currently owns foreground interaction.',
    'Signals report asynchronous events to processes or threads under the operating system’s signal model. A disposition selects a default action, an installed handler, or an allowed ignore behavior. A signal mask temporarily blocks delivery of selected signals. These mechanisms let a shell observe children, interrupt a job, and regain terminal control.'
  ], [
    trace('Foreground pipeline with two members', ['Event', 'Shell', 'Job processes', 'Terminal foreground group'], [['Before launch','PID/PGID 700 owns prompt','None','700'],['Create pipeline','Records a job with PGID 711','PIDs 711 and 712 join PGID 711','700 during construction'],['Give terminal to job','Waits for job state changes','Both processes execute','711'],['User enters interrupt character','Shell stays outside the target foreground group','Terminal sends the configured interrupt signal to group 711','711'],['Job finishes or fully stops','Collects status and retakes terminal','Exit or stop state is recorded for each member','700']]),
    prose('Install the job before child notifications can race',
      'A child can exit immediately after creation. If the shell handles its notification before installing the child in its job table, it can lose the association between the PID and the pending job. A common construction protocol blocks the child-status signal, creates children and assigns their group, installs the records, then restores the prior mask. Parent and child cooperate in process-group assignment to close scheduling races.',
      'Before executing a program, a child restores the signal mask and dispositions appropriate for an ordinary foreground program. A shell may ignore or handle terminal-control signals for its own bookkeeping; blindly inheriting those choices can make a child unexpectedly ignore an interrupt. The executor also closes unused descriptors, as established by the pipeline lesson.'),
    steps('Process child-status events in normal execution', [['Treat notification as a prompt','A notification means some child state may have changed. Standard signals can coalesce, so one notification can cover several changes.'],['Drain available status','Call the nonblocking wait interface repeatedly with the desired exit, stop, and continue options until no further status is available.'],['Update every process record','Record which pipeline members are running, stopped, or terminated; retain exit information until collected by the shell policy.'],['Derive the job state','A pipeline is complete when all members have terminated. A stopped job requires a documented group-level rule that accounts for remaining live members.'],['Restore terminal ownership','When the foreground job finishes or becomes fully stopped, give the terminal back to the shell and restore any saved terminal settings.']]),
    prose('Keep handlers small and coordinate sleep atomically',
      'A signal handler can interrupt a library routine while its internal state is inconsistent. Use only operations permitted by the platform’s async-signal-safety contract. A minimal handler can set a volatile sig_atomic_t flag; another design writes to a nonblocking self-pipe so the event loop receives a normal readiness event. Allocation, formatted output, and arbitrary container manipulation usually belong in the main loop.',
      'Checking a flag and then blocking in an unrelated wait can lose an opportunity to wake if the signal arrives between those actions. Use an interface such as pselect or sigsuspend with the documented atomic mask-and-wait behavior, or an equivalent kernel protocol. The main loop then drains child statuses and reevaluates its condition after wakeup.',
      'Terminal input also passes through a line discipline. In canonical mode, editing and special input characters can affect when a read completes. The end-of-file character can complete a pending line or produce a zero-length read at an empty line under that discipline. It is a terminal input rule, distinct from sending a process-control signal. A teaching shell can begin with a simpler terminal contract and add job control deliberately.'),
    exercise('One notification, two child exits', 'Both members of a pipeline exit before the shell handles a single pending child-status notification.', ['Explain why one wait call is insufficient as a general notification handler.', 'State which process group should receive terminal interrupts while a job runs and after the shell retakes the prompt.'], ['Drain all currently available child statuses, because notifications can coalesce. One wait may collect only one member and leave the other record stale until another event occurs.', 'While the job runs, its foreground process group receives the terminal-generated control signal. After terminal ownership returns, the shell’s group is foreground and applies the shell’s own handling policy.'], ['Both child records are updated.', 'Foreground terminal ownership follows the active job.'])
  ], [osc('Chapter 3: Process control and signals'), reference('Linux signal overview','https://man7.org/linux/man-pages/man7/signal.7.html','Dispositions, masks, pending signals, and delivery'), reference('Terminal foreground process group','https://man7.org/linux/man-pages/man3/tcsetpgrp.3.html','Session and terminal process-group rules')])
];

systemsFurtherHandbook['capstone'] = [
  topic('threat-model-authentication-lifecycle', 'definition', 'Connect a threat model to authentication, sessions, and resource limits', [
    'A threat model identifies assets, adversary capabilities, trust boundaries, and the properties the system must preserve. Start with one concrete deployment: a teaching OS accepts untrusted user programs and removable filesystem images, while its kernel image and initial administrator configuration are trusted. Expand those assumptions explicitly when adding a network service or remote administration.',
    'Confidentiality protects information from unauthorized observation. Integrity protects state from unauthorized change. Availability protects useful service from disruption within the stated threat model. A memory-safe parser can still consume unbounded time, so the property being tested determines which bounds and controls are required.'
  ], [
    table('Turn threats into observable requirements', ['Input or actor', 'Asset at risk', 'Required evidence'], [['Malformed filesystem image','Kernel memory and availability','Every offset and traversal is bounded; malformed input returns a controlled failure'],['Unprivileged process','Other processes’ memory and kernel state','Page permissions and syscall authorization reject prohibited access'],['Repeated login attempts','Account access and service capacity','Verification work and attempt rates are bounded under a documented policy'],['Stolen session handle','Account authority','Expiration, revocation, transport protection, and privilege scope are tested']]),
    prose('Separate verification from long-lived authority',
      'Password authentication verifies knowledge against a stored verifier. A salt makes identical passwords produce distinct records and prevents a single precomputed table from matching every account. A purpose-built password derivation function supplies a configurable work and memory cost; production parameters should follow current primary guidance and measured deployment limits. Store the algorithm identifier, salt, parameters, and verifier so records can be upgraded after a successful login.',
      'After authentication, create a session with an unpredictable identifier and the intended authority. Check session validity and authorization when processing protected operations. Password changes, account suspension, logout, and privilege reduction need explicit policies for existing sessions. A correct password comparison alone leaves those later lifecycle decisions unresolved.'),
    trace('A token-bucket admission model for verification work', ['Time', 'Bucket state before requests', 'Requests admitted'], [['0 seconds','Capacity 4, initially full','First four attempts consume four tokens; a fifth waits or is rejected'],['15 seconds','0.5 token after continuous refill at one per 30 seconds','A one-token attempt still lacks capacity'],['30 seconds','1 token if no intervening admission','One attempt can proceed; bucket returns to zero'],['Long idle period','Refill stops at capacity 4','The burst allowance remains bounded']]),
    prose('Calculate the purpose of a costly verifier',
      'For a hypothetical measured verifier cost of 25 ms per guess, one worker evaluating a million guesses takes 25000 seconds, about 6.94 hours. Sixty-four perfectly independent workers reduce that ideal time to 390.625 seconds, about 6.51 minutes. This arithmetic illustrates why verification cost and password quality both matter. Actual parallel scaling depends on memory, hardware, and the selected derivation function; these constants are teaching inputs.',
      'Online rate limits constrain requests reaching the service, while a stolen verifier database permits offline work outside those limits. Use separate controls for those two cases. An account-only lockout can itself deny service to a victim, so practical policy also considers source limits, recovery, monitoring, and bounded verification queues. Capacity reservation must happen atomically before expensive work begins.'),
    steps('Review the complete authentication path', [['Bound input and work','Limit identifier length, credential input, concurrent verification jobs, and retained failure state.'],['Verify with a trusted implementation','Use the chosen password or public-key verification library and its constant-time comparison facilities where required.'],['Issue scoped authority','Create a fresh session and associate the permitted account or capability set.'],['Enforce lifecycle rules','Apply expiration, revocation, and privilege changes at the protected-operation boundary.'],['Test failures','Exercise wrong credentials, malformed records, verifier-resource exhaustion, expired sessions, and recovery without exposing secret material in logs.']]),
    exercise('Account for a verification queue', 'A service allows four concurrent verification jobs. Each takes 50 ms on its assigned worker, and there are four workers with no other bottleneck.', ['Calculate ideal maximum verification throughput.', 'Explain what an unbounded waiting queue would allow an attacker to consume even with the concurrency limit.'], ['Each worker completes 20 jobs per second; four workers provide at most 80 per second under these assumptions.', 'An unbounded queue can consume memory and make legitimate requests wait arbitrarily long. Bound admission and queued state as well as concurrent execution, then return an explicit overload result or apply a documented waiting policy.'], ['Ideal throughput 80 verifications per second.', 'Both queued and executing work have limits.'])
  ], [ost('security-intro','Chapter 53: Security goals and threat models'), ost('security-authentication','Chapter 54: Authentication'), osc('Chapter 16: Security'), reference('NIST SP 800-63B-4','https://csrc.nist.gov/pubs/sp/800/63/b/4/final','Authentication and authenticator management')]),

  topic('vm-scheduling-io-live-migration', 'architecture', 'Coordinate virtual CPUs, device queues, and a live-migration handoff', [
    'A guest scheduler chooses a guest thread for a virtual CPU, while a host scheduler decides when that virtual CPU receives a real CPU. Guest-visible delay can therefore include time when the guest considers work runnable but the host has descheduled its virtual CPU. Diagnose both scheduling layers when a virtual machine stalls under host contention.',
    'Device virtualization also has multiple implementations. An emulated device presents a hardware-compatible register interface. A paravirtualized device uses an interface designed for cooperation between guest and host, often with shared request rings and explicit notifications. Both require validated descriptors, owned buffers, and completion rules.'
  ], [
    table('One virtual machine crosses several ownership boundaries', ['State', 'Owner while running', 'Migration requirement'], [['vCPU registers and control state','Hypervisor and executing guest','Capture a coherent stopped state for every virtual CPU'],['Guest RAM','Guest mappings backed by host memory','Track and transfer changed pages until the final handoff'],['Virtual device queues','Guest and device backend under their protocol','Preserve descriptors, completion state, and outstanding ownership'],['External storage and network identity','Deployment-specific services','Coordinate access and prevent two active owners after handoff']]),
    prose('Use batching to reduce notification cost',
      'Assume an emulated operation causes twelve intercepted accesses, each costing an illustrative 3 microseconds. That path spends 36 microseconds on those exits. A cooperative queue using one submission notification and one completion notification would spend 6 microseconds on those two events, plus its queue-management costs. This comparison isolates notification frequency; it does not supply a hardware benchmark or imply that every queue operation requires a VM exit.',
      'A descriptor ring needs producer and consumer indices, ordering before ownership publication, and a bounded capacity rule. The host validates lengths and guest addresses before accessing buffers. A malicious guest must remain inside its memory and device authority even when its descriptor fields change concurrently. The same snapshot and ownership reasoning used for syscalls applies at this boundary.'),
    trace('Pre-copy a 2048 MiB guest with a simple dirty-page model', ['Round', 'Data copied', 'At 512 MiB/s', 'New dirty data at 128 MiB/s'], [['Initial pass','2048 MiB','4 s','512 MiB'],['Second pass','512 MiB','1 s','128 MiB'],['Third pass','128 MiB','0.25 s','32 MiB'],['Stop-and-copy tail','32 MiB','0.0625 s','Guest is paused, so this model creates no new dirty pages']]),
    prose('Derive convergence and downtime',
      'In this model, each round leaves a fraction dirty_rate/copy_rate=128/512=1/4 of the amount just copied. Pre-copy therefore shrinks the remaining work geometrically. If dirtying equals or exceeds effective copy bandwidth, that simple process fails to shrink the remainder. A migration policy then needs a bounded stopping rule, workload throttling, another technique, or a declared failure to meet the requested downtime.',
      'If final CPU and device state takes another 10 ms, the modeled pause is 62.5+10=72.5 ms. The earlier 5.25 seconds of copying occur while the guest continues to run. Real dirty sets can contain repeated writes to the same page, changing rates, compression, and network contention, so record measured remaining bytes and actual bandwidth each round.'),
    steps('Commit one active owner', [['Prepare destination','Check compatible virtual hardware, sufficient memory, and access to required storage and network resources.'],['Copy while tracking writes','Transfer RAM and record pages modified after they were copied. Keep source execution authoritative during preparation.'],['Pause and quiesce','Stop all virtual CPUs at a coherent boundary and capture device state, interrupts, timers, and the remaining memory changes.'],['Transfer final state','Validate the destination’s complete state and establish any external resource fencing or ownership token.'],['Resume destination','Activate one destination owner, then retire the source under a recovery protocol that handles a failed handoff without dual writers.']]),
    exercise('A faster-dirtying guest', 'A guest has 1024 MiB of RAM, effective copy bandwidth 256 MiB/s, and dirty rate 64 MiB/s under the same simple model.', ['Calculate the initial pass time and the next two remaining dirty amounts.', 'Compute final memory-copy downtime if the guest is stopped with 16 MiB remaining.'], ['The initial pass takes four seconds and leaves 256 MiB dirty. Copying that takes one second and leaves 64 MiB; copying 64 MiB takes 0.25 seconds and leaves 16 MiB.', 'Copying the final 16 MiB takes 16/256=0.0625 seconds, or 62.5 ms, before additional CPU/device-state and handoff costs.'], ['Dirty fraction is one quarter per round.', 'Only one machine owns the resumed guest.'])
  ], [ost('vmm-intro','Appendix: Virtual Machine Monitors'), osc('Chapter 18: Virtual Machines'), reference('QEMU migration framework','https://www.qemu.org/docs/master/devel/migration/main.html','RAM transfer, device state, and migration phases')]),

  topic('replicated-register-consistency-quorums', 'testing', 'Check consistency histories and derive a majority-register protocol', [
    'Replication creates several copies of state, so an interface must specify what a read may observe. Linearizability requires each operation to behave as if it took effect at one point between invocation and response, while respecting real-time order between completed operations. Eventual convergence permits temporary differences while requiring replicas to converge under its assumptions after updates stop.',
    'Use five replicas A through E and a single writer that assigns strictly increasing version numbers. Each replica stores a version/value pair and never replaces it with an older version. Assume crash-stop failures, reliable eventual message delivery among a reachable majority, and no malicious replicas. These assumptions define the scope of the following teaching protocol.'
  ], [
    table('Evaluate two register histories', ['History', 'Read result', 'Linearizability implication'], [['Write version 8 returns before read begins','Read returns version 7','Violates the completed-write order'],['Read overlaps an unfinished write of version 8','Read returns version 7','Can be valid if the read takes effect before that concurrent write']]),
    prose('Derive the majority intersection',
      'A majority of five contains three replicas. Two such sets intersect because 3+3 exceeds 5; at least one replica belongs to both. If a completed write is retained on three replicas, every later three-replica query reaches at least one holder of that version or a newer one. Two crashes can still leave a reachable majority. A partition exposing only two reachable replicas cannot complete this majority-based operation.',
      'Intersection supplies the overlap used by the proof. Version ordering, replica update rules, and read propagation supply the remaining protocol. A reader that observes an incompletely propagated newer value can otherwise return that value while a later reader returns an older one.'),
    trace('Why a reader propagates the version it returns', ['Step', 'Replica state or query', 'Result'], [['1','Version 8 is on A,B,C; a new version 9 has reached only A','A has 9; B,C have 8; D,E may be older'],['2','Reader R1 queries A,B,C','Highest observed version is 9'],['3, incomplete design','R1 returns 9 without propagation; later R2 queries B,C,D','R2 can return 8 after R1 completed'],['3, repaired protocol','R1 first writes version 9 back to a majority such as A,D,E','Every later majority intersects a holder of version 9 or newer']]),
    code('Single-writer majority register', 'text', `write(value):
    version = next strictly increasing writer version
    send STORE(version, value) to all replicas
    wait for acknowledgements from any three
    return success

read():
    send QUERY with a fresh operation identifier to all replicas
    wait for replies from any three
    chosen = reply with greatest version
    send STORE(chosen.version, chosen.value) to all replicas
    wait for acknowledgements from any three
    return chosen.value

replica STORE(version, value):
    if version > local.version: retain the new pair
    if version == local.version: require the same value
    acknowledge while preserving any newer local pair`,
      'The single writer serializes its writes and never reuses a version for another value. A crash-recovery extension needs durable version and replica-state rules; this example assumes crash-stop failures.',
      'Request identifiers keep replies from different operations separate. Acknowledgements belong to the current store phase, even when a replica already retains a newer pair.'),
    prose('State the progress and generalization limits',
      'A read has two majority phases, so it pays an extra communication round to stabilize the version it returns. Its writeback can complete a value whose writer stopped before acknowledging success. This is compatible with the register model because an incomplete write can take effect during a concurrent history. Failed or timed-out calls therefore require carefully stated outcome semantics.',
      'Multiple writers need a version-selection protocol that orders their updates correctly. Arbitrary replicated commands such as increment, transfer, or allocate also require an agreed operation order if every replica must execute the same state machine. A consensus protocol such as Raft addresses a broader replicated-log problem with leader, term, and commitment rules. Replacing those rules with a count of acknowledgements would omit the ordering argument.'),
    exercise('Check a seven-replica design', 'There are seven replicas and every query or store phase waits for four. A completed read wrote its chosen version to replicas A,B,C,D.', ['Compute the minimum intersection of any two four-replica sets and the number of crash-stop failures compatible with a remaining majority.', 'Explain what a later query to D,E,F,G must observe under the monotonic-version rule.'], ['The minimum intersection is 4+4-7=1. Three failed replicas can leave four available; progress still requires those four to communicate.', 'Replica D retains the completed read’s version or a newer one. The later query therefore selects at least that version, then performs its own majority writeback before returning.'], ['Minimum intersection 1; tolerate at most 3 crash stops for majority availability.', 'Completed reads cannot be followed by an older returned version in this protocol.'])
  ], [ost('dist-intro','Chapter 48: Distributed failures and communication'), osc('Chapter 19: Distributed systems and consistency'), reference('Attiya, Bar-Noy, and Dolev: Sharing Memory Robustly','https://groups.csail.mit.edu/tds/papers/Attiya/JACM95.pdf','Single-writer atomic registers over message passing'), reference('Raft original paper','https://raft.github.io/raft.pdf','Replicated state machines, terms, and commitment')])
];
